const b = $input.first().json;
if (!b || typeof b.recipient !== 'string' || b.recipient.trim() !== b.recipient || b.recipient.length > 254 || !/^[a-zA-Z0-9._+-]+@example\.invalid$/.test(b.recipient) || typeof b.subject !== 'string' || !b.subject.startsWith('Tonia — TEST LOCAL — ') || /[\r\n]/.test(b.subject) || b.subject.length > 200 || typeof b.text !== 'string' || !b.text.trim() || b.text.length > 650000) throw new Error('Test local : seules les données fictives et une adresse @example.invalid sont autorisées.');
return [{json:{recipient:b.recipient,subject:b.subject,text:b.text}}];

const info = $input.first().json;
const recipient = $('Verifier recette').first().json.recipient;
if (!info.messageId || !Array.isArray(info.accepted) || !info.accepted.includes(recipient) || (Array.isArray(info.rejected) && info.rejected.length)) throw new Error('Acceptation SMTP locale non confirmée.');
return [{json:{mode:'TEST_LOCAL',acceptedLocally:true,messageId:info.messageId,externalDelivery:false,mailpitUrl:'http://localhost:8025',notice:'Accepté par Postfix. Vérifier ensuite la capture dans Mailpit. Aucun envoi externe.'}}];
